SELECT equipmentcode, performanceindex, reliabilityindex, environmentalimpactindex, 
       ((performanceindex + reliabilityindex) / 2.0) * (1.0 - environmentalimpactindex / 100.0) AS eer_alt
FROM equipment LIMIT 5;

